## A `loadForm` application that imports only the modules its form uses (the
## shape of a form unit generated by the IDE). tformload_light.nim compiles it
## and checks that the property registry is not part of the program.
import nimvcl/core/[control, form, application]
import nimvcl/controls/[label, edit, button, imagelist, menus, listbox, trackbar, pagecontrol]
import nimvcl/dsl/formload

loadForm Light, "lightapp.nfm"

var clicks = 0
proc button1Click(self: Light, sender: Control) = inc clicks

proc main() =
  Application.init()
  let f = newLight()
  doAssert f.name == "Light"
  doAssert f.edit1.text == "hello"
  doAssert f.button1.caption == "OK"
  doAssert f.icons.images.len == 1
  doAssert f.fileMenu.shortcut == shortcut("Ctrl+Q")
  # the file lists these properties before the ones they depend on
  doAssert f.list1.itemIndex == 1
  doAssert f.tabs1.tabIndex == 2
  doAssert f.track1.position == 70
  f.button1.onClick(f.button1)
  doAssert clicks == 1
  f.show()
  Application.processMessages()
  Application.shutdown()
  echo "light ok"

main()
